import os
from contextlib import contextmanager

from taf.config.scf import scf

from taf.ul.config.scf.exceptions import MissingParentObject


class SCFOperations(object):
    __DEFAULT_OBJECT_OPERATION = 'create'

    def __init__(self):
        self.scf = scf()

    def toggling_in_scf(self, path_to_scf, path_to_new_scf, mnlent_number,
                        al_togg_amount, al_togg_clearance_time,
                        al_togg_condition_time, fault_name, in_use):
        self.scf.load_scf(path_to_scf)
        dist_name = 'MRBTS-1900/MNL-1/MNLENT-{}/FMCADM-1'.format(mnlent_number)
        list_name = 'alToggSuppList'
        elements = {'alToggAmount': al_togg_amount,
                    'alToggClearanceTime': al_togg_clearance_time,
                    'alToggConditionTime': al_togg_condition_time,
                    'faultName': fault_name,
                    'inUse': in_use}
        self.scf.add_item_to_list(dist_name, list_name, elements)
        self.scf.save_scf(path_to_new_scf)

    def prepare_scf_file(self, scf_path, should_contain=None, should_not_contain=None):
        """
        Prepares SCF file by ensuring, that entries from should_contain list are present in SCF file and
        entries from should_not_contain list are absent from SCF file.
        Handles following SCF entries: objects, elements, lists with items, lists with simple elements.

        Adding or modifying:
          - object: should_contain=[dict(dist_name='MRBTS-1900/TNLSVC-1/TNL-4',
                                         class_name='com.nokia.srbts.tnl:TNL',
                                         version='TNL5G18A_1803_001',
                                         operation='create')]
            Note: parent object (i.e. 'MRBTS-1900') must be specified before it's children (i.e. 'MRBTS-1900/TNLSVC-1')
            in should_contain list.
          - element: should_contain=[dict(dist_name='MRBTS-1900/TNLSVC-1/TNL-4',
                                          p_name='neType',
                                          value='FSM')]
          - list with items: should_contain=[dict(dist_name='MRBTS-1900/NRBTS-1/NRCELL-1',
                                                  list_name='beamSet',
                                                  items=[dict(basicBeamSet='beamSet_1'),
                                                         dict(basicBeamSet='beamSet_2')])]
          - list with simple elements: should_contain=[dict(dist_name='MRBTS-1900/NRBTS-1/NRCELLGRP-0',
                                                            list_name='nrCellList',
                                                            items=['1', '2'])]
        Removing:
          - object: should_not_contain=[dict(dist_name='MRBTS-1900/TNLSVC-1/TNL-4')]
          - element: should_not_contain=[dict(dist_name='MRBTS-1900/TNLSVC-1/TNL-4',
                                              p_name='neType')]
          - list: should_not_contain=[dict(dist_name='MRBTS-1900/NRBTS-1/NRCELL-1',
                                           list_name='beamSet')]

        :param scf_path: path to SCF file which will be prepared, i.e. 'scf_files/SBTS5G18A_5g_pid11.xml'
        :type scf_path: str
        :param should_contain: list of entries which should be present in prepared SCF file
        :type should_contain: list of dicts
        :param should_not_contain: list of entries which should be absent from prepared SCF file
        :type should_not_contain: list of dicts
        """
        self._check_path(scf_path)

        if should_contain:
            for scf_entry in should_contain:
                self._contain_scf_entry(scf_path, scf_entry)

        if should_not_contain:
            for scf_entry in should_not_contain:
                self._remove_scf_entry(scf_path, scf_entry)

    def _check_path(self, scf_path):
        """
        Checks whether path to SCF file is correct.
        :param scf_path: SCF file path which will be checked
        :type scf_path: str
        :raises ValueError: raised when SCF file path is empty
        :raises IOError: raised when SCF file path doesn't exist
        """
        if not scf_path:
            raise ValueError("Path to SCF file cannot be empty")

        if not os.path.isfile(scf_path):
            raise IOError("Path to SCF file '{}' must exist".format(scf_path))

    def _contain_scf_entry(self, scf_path, scf_entry):
        """
        Ensures that given SCF entry will be contained in SCF file, either by adding or modifying it.
        :param scf_path: path to SCF file
        :type scf_path: str
        :param scf_entry: data of SCF entry which will be contained, i.e. dict(dist_name='MRBTS-1900/TNLSVC-1/TNL-4',
                                                                               p_name='neType',
                                                                               value='FSM')
        :type scf_entry: dict
        """
        with self._open_scf(scf_path):
            if self._is_a_list(scf_entry):
                self._validate_list(scf_entry)
                self._contain_list(scf_entry)
            elif self._is_an_element(scf_entry):
                self._contain_element(scf_entry)
            else:
                self._contain_object(scf_entry)

    def _remove_scf_entry(self, scf_path, scf_entry):
        """
        Ensures that given SCF entry will be not be present in SCF file.
        :param scf_path: path to SCF file
        :type scf_path: str
        :param scf_entry: data of SCF entry which will not be removed i.e. dict(dist_name='MRBTS-1900/TNLSVC-1/TNL-4',
                                                                                p_name='neType',
                                                                                value='FSM')
        :type scf_entry: dict
        """
        with self._open_scf(scf_path):
            if self._is_a_list(scf_entry):
                self._remove_list(scf_entry)
            elif self._is_an_element(scf_entry):
                self._remove_element(scf_entry)
            else:
                self._remove_object(scf_entry)

    @contextmanager
    def _open_scf(self, scf_path):
        """
        Context manager for loading and saving SCF file.
        :param scf_path: path to SCF file which will be opened
        :type scf_path: str
        """
        self.scf.load_scf(scf_path)
        yield self.scf
        self.scf.save_scf(scf_path)

    def _is_a_list(self, scf_entry):
        """
        Checks whether given SCF entry is a list.
        :param scf_entry: data of SCF entry which will be checked, i.e. dict(dist_name='MRBTS-1900/NRBTS-1/NRCELL-1',
                                                                             list_name='beamSet',
                                                                             items=[dict(basicBeamSet='beamSet_1',
                                                                                         leftEdgeAngle='60')])
        :type scf_entry: dict
        :return: True if given SCF entry is a list, False otherwise.
        :rtype: bool
        """
        return 'list_name' in scf_entry

    def _contain_list(self, scf_list):
        """
        Ensures that given list will be contained in SCF file, either by adding or replacing it.
        :param scf_list: data of list which will be contained, i.e. dict(dist_name='MRBTS-1900/NRBTS-1/NRCELL-1',
                                                                         list_name='beamSet',
                                                                         items=[dict(basicBeamSet='beamSet_1',
                                                                                     leftEdgeAngle='60')])
        :type scf_list: dict
        """
        if self.scf.is_list_in_object(scf_list['dist_name'], scf_list['list_name']):
            self._replace_list(scf_list)
        else:
            self._add_list(scf_list)

    def _validate_list(self, scf_list):
        """
        Checks whether given list have correct items.
        :param scf_list: data of list which will be checked, i.e. dict(dist_name='MRBTS-1900/NRBTS-1/NRCELL-1',
                                                                       list_name='beamSet',
                                                                       items=[dict(basicBeamSet='beamSet_1',
                                                                                   leftEdgeAngle='60')])
        :type scf_list: dict
        :except ValueError: raised when list contains incorrect items or doesn't contain items at all
        """
        list_name = scf_list['list_name']

        if 'items' not in scf_list or not scf_list['items']:
            raise ValueError('List {} must contain one or more items'.format(list_name))

        if not all(scf_list['items']):
            raise ValueError('List {} cannot have empty items'.format(list_name))

        if self._is_any_item_a_dictionary(scf_list['items']) and self._is_any_item_not_a_dictionary(scf_list['items']):
            raise ValueError('List {} cannot have items and elements at the same time'.format(list_name))

    def _is_any_item_a_dictionary(self, items):
        """
        Checks whether any list item is a dictionary.
        :param items: list items which will be checked, i.e. [dict(eea0='1', eea2='9'),
                                                              dict(eea1='5', eea3='7')]
        :type items: list
        :return: True if any list item is a dictionary, False otherwise
        :rtype: bool
        """
        return any(type(item) is dict for item in items)

    def _is_any_item_not_a_dictionary(self, items):
        """
        Checks whether any list item is not a dictionary.
        :param items: list items which will be checked, i.e. [dict(eea0='1', eea2='9'),
                                                              dict(eea1='5', eea3='7')]
        :type items: list
        :return: True if any list item is not a dictionary, False otherwise
        :rtype: bool
        """
        return any(type(item) is not dict for item in items)

    def _replace_list(self, scf_list):
        """
        Replaces given list in SCF file.
        :param scf_list: data of list which will be replaced, i.e. dict(dist_name='MRBTS-1900/NRBTS-1/NRCELL-1',
                                                                        list_name='beamSet',
                                                                        items=[dict(basicBeamSet='beamSet_1',
                                                                                    leftEdgeAngle='60')])
        :type scf_list: dict
        """
        self._remove_list(dict(dist_name=scf_list['dist_name'], list_name=scf_list['list_name']))
        self._add_list(scf_list)

    def _add_list(self, scf_list):
        """
        Adds given list to SCF file.
        If object, to which list should be added, doesn't exist, it will be added too.
        :param scf_list: data of list which will be added, i.e. dict(dist_name='MRBTS-1900/NRBTS-1/NRCELL-1',
                                                                     list_name='beamSet',
                                                                     items=[dict(basicBeamSet='beamSet_1',
                                                                                 leftEdgeAngle='60')])
        :type scf_list: dict
        """
        dist_name = scf_list['dist_name']
        list_name = scf_list['list_name']

        if not self.scf.is_object_in_scf(dist_name):
            self._add_object(dict(dist_name=dist_name,
                                  class_name=scf_list.get('class_name'),
                                  version=scf_list.get('version'),
                                  operation=scf_list.get('operation', self.__DEFAULT_OBJECT_OPERATION)))

        self.scf.add_list_to_scf(dist_name, list_name)
        self._add_items_to_list(dist_name, list_name, scf_list['items'])

    def _add_items_to_list(self, dist_name, list_name, items):
        """
        Adds given items to list in SCF file.
        :param dist_name: name of object which contains list, i.e. 'MRBTS-1900/NRBTS-1'
        :type dist_name: str
        :param list_name: name of list to which items will be added, i.e. 'f1Cplane'
        :type list_name: str
        :param items: items which will be added to list, i.e. [dict(eea0='1', eea2='9'),
                                                               dict(eea1='5', eea3='7')]
        :type items: list
        """
        if self._are_all_items_dictionaries(items):
            for item in items:
                self.scf.add_item_to_list(dist_name, list_name, item)
        elif self._are_all_items_not_dictionaries(items):
            self.scf.add_elements_to_list(dist_name, list_name, items)

    def _are_all_items_dictionaries(self, items):
        """
        Checks whether all list items are a dictionaries.
        :param items: list items which will be checked, i.e. [dict(eea0='1', eea2='9'),
                                                              dict(eea1='5', eea3='7')]
        :type items: list
        :return: True if all list items are a dictionaries, False otherwise
        :rtype: bool
        """
        return all(type(item) is dict for item in items)

    def _are_all_items_not_dictionaries(self, items):
        """
        Checks whether all list items are not a dictionaries.
        :param items: list items which will be checked, i.e. ['1', '2', '3']
        :type items: list
        :return: True if all list items are not a dictionaries, False otherwise
        :rtype: bool
        """
        return all(type(item) is not dict for item in items)

    def _remove_list(self, scf_list):
        """
        Removes given list from SCF file.
        :param scf_list: data of list which will be removed, i.e. dict(dist_name='MRBTS-1900/NRBTS-1/NRCELL-1',
                                                                       list_name='beamSet')
        :type scf_list: dict
        """
        if self.scf.is_list_in_object(scf_list['dist_name'], scf_list['list_name']):
            self.scf.remove_list_from_scf(scf_list['dist_name'], scf_list['list_name'])

    def _is_an_element(self, scf_entry):
        """
        Checks whether given SCF entry is an element.
        :param scf_entry: data of SCF entry which will be checked, i.e. dict(dist_name='MRBTS-1900/TNLSVC-1/TNL-4',
                                                                             p_name='neType',
                                                                             value='FSM')
        :type scf_entry: dict
        :return: True if given SCF entry is an element, False otherwise.
        :rtype: bool
        """
        return 'p_name' in scf_entry

    def _contain_element(self, element):
        """
        Ensures that given element will be contained in SCF file, either by adding or modifying it.
        :param element: data of element which will be contained, i.e. dict(dist_name='MRBTS-1900/TNLSVC-1/TNL-4',
                                                                           p_name='neType',
                                                                           value='FSM')
        :type element: dict
        """
        if self.scf.is_element_in_object(element['dist_name'], element['p_name']):
            self._modify_element(element)
        else:
            self._add_element(element)

    def _modify_element(self, element):
        """
        Modifies given element in SCF file.
        :param element: data of element which will be modified, i.e. dict(dist_name='MRBTS-1900/TNLSVC-1/TNL-4',
                                                                          p_name='neType',
                                                                          value='FSM')
        :type element: dict
        """
        self.scf.modify_scf_element(dist_name=element['dist_name'], p_name=element['p_name'], value=element['value'])

    def _add_element(self, element):
        """
        Adds given element to SCF file.
        If object, to which element should be added, doesn't exist, it will be added too.
        :param element: data of element which will be added, i.e. dict(dist_name='MRBTS-1900/TNLSVC-1/TNL-4',
                                                                       p_name='neType',
                                                                       value='FSM')
        :type element: dict
        """
        if not self.scf.is_object_in_scf(element['dist_name']):
            self._add_object(dict(dist_name=element.get('dist_name'),
                                  class_name=element.get('class_name'),
                                  version=element.get('version'),
                                  operation=element.get('operation', self.__DEFAULT_OBJECT_OPERATION)))

        self.scf.add_element_to_scf(dist_name=element['dist_name'], p_name=element['p_name'], value=element['value'])

    def _remove_element(self, element):
        """
        Removes given element from SCF file.
        :param element: data of element which will be removed, i.e. dict(dist_name='MRBTS-1900/TNLSVC-1/TNL-4',
                                                                          p_name='neType')
        :type element: dict
        """
        if self.scf.is_element_in_object(element['dist_name'], element['p_name']):
            self.scf.remove_element_from_scf(**element)

    def _contain_object(self, scf_object):
        """
        Ensures that given object will be contained in SCF file, either by adding or modifying it.
        :param scf_object: data of object which will be contained, i.e. dict(dist_name='MRBTS-1900/TNLSVC-1/TNL-4',
                                                                             class_name='com.nokia.srbts.tnl:TNL',
                                                                             version='TNL5G18A_1803_001',
                                                                             operation='create')
        :type scf_object: dict
        """
        if self.scf.is_object_in_scf(scf_object['dist_name']):
            self._replace_object(scf_object)
        else:
            self._add_object(scf_object)

    def _replace_object(self, scf_object):
        """
        Replaces given object in SCF file.
        :param scf_object: data of object which will be replaced, i.e. dict(dist_name='MRBTS-1900/TNLSVC-1/TNL-4',
                                                                            class_name='com.nokia.srbts.tnl:TNL',
                                                                            version='TNL5G18A_1803_001',
                                                                            operation='create')
        :type scf_object: dict
        """
        self._remove_object(dict(dist_name=scf_object['dist_name']))
        self._add_object(scf_object)

    def _add_object(self, scf_object):
        """
        Adds given object to SCF file.
        :param scf_object: data of object which will be added, i.e. dict(dist_name='MRBTS-1900/TNLSVC-1/TNL-4',
                                                                         class_name='com.nokia.srbts.tnl:TNL',
                                                                         version='TNL5G18A_1803_001',
                                                                         operation='create')
        :type scf_object: dict
        """
        self._check_object(scf_object)
        self._check_parent_object(scf_object)
        self.scf.add_object_to_scf(**scf_object)

    def _check_parent_object(self, scf_object):
        """
        Checks whether given object has existing parent object in SCF file.
        :param scf_object: data of child object for which parent object will be searched,
                           i.e. dict(dist_name='MRBTS-1900/TNLSVC-1/TNL-4',
                                     class_name='com.nokia.srbts.tnl:TNL',
                                     version='TNL5G18A_1803_001',
                                     operation='create')
        :type scf_object: dict
        :except MissingParentObject: when parent object does not exist in SCF file
        """
        child_dist_name = scf_object['dist_name']
        parent_dist_name = '/'.join(child_dist_name.split('/')[:-1])

        if not self.scf.is_object_in_scf(parent_dist_name):
            raise MissingParentObject("Can't add object '{}' because it's parent '{}' does not exist".format(
                child_dist_name, parent_dist_name))

    def _check_object(self, scf_object):
        """
        Checks whether given object has correct content.
        :param scf_object: data of object which will be checked, i.e. dict(dist_name='MRBTS-1900/TNLSVC-1/TNL-4',
                                                                            class_name='com.nokia.srbts.tnl:TNL',
                                                                            version='TNL5G18A_1803_001',
                                                                            operation='create')
        :type scf_object: dict
        :except ValueError: raised when object doesn't contain required data: class_name and version.
        """
        if 'class_name' not in scf_object or not scf_object['class_name']:
            raise ValueError('Specified class_name is required when creating object {}'.format(
                scf_object['dist_name']))

        if 'version' not in scf_object or not scf_object['version']:
            raise ValueError('Specified version is required when creating object {}'.format(scf_object['dist_name']))

    def _remove_object(self, scf_object):
        """
        Removes given object from SCF file.
        :param scf_object: data of object which will be removed, i.e. dict(dist_name='MRBTS-1900/TNLSVC-1/TNL-4')
        :type scf_object: dict
        """
        if self.scf.is_object_in_scf(scf_object['dist_name']):
            self.scf.remove_mo_with_descendant_mos(scf_object['dist_name'])
